    'when.finale': 'the finale',
    when: 'episode {ep}',
    intro: 'You crowd into the galley for {when} of "{title}", a {genre}. The screen is the size of a dinner tray, braced against the coffee maker with a rolled blanket, and the sound is turned up until it\'s just under the air handler.',
    fans: '{names} know every line, and say them half a second before the actors do, until somebody throws a spoon.',
